def main(package: str, response: str) -> dict:
    p=json.loads(package)
    if not isinstance(response,str) or len(response)>5000: raise ValueError('Invalid simulation response')
    try: a=json.loads(response)
    except (ValueError,TypeError): raise ValueError('Use the review form; natural language interpretation is disabled')
    if not isinstance(a,dict): raise ValueError('Expected review object')
    a=a.get('answers',a)
    if not isinstance(a,dict) or set(a)!={'review'} or not isinstance(a['review'],dict): raise ValueError('Expected review answers')
    a=a['review']
    if set(a)-{'title','ending'} or a.get('ending') not in ('share','celebrate'): raise ValueError('Choose a supported ending')
    title=a.get('title','')
    if not isinstance(title,str) or len(title)>80: raise ValueError('Title exceeds bounds')
    p['title']=title.strip() or p['title'];p['ending']=a['ending']
    ending='share the rescued kite.' if p['ending']=='share' else 'celebrate their rescue.'
    p['stages']['J02']['resolution']='Together they '+ending
    p['stages']['J03']={'characters':[{'id':'mina','role':'inventor'},{'id':'pip','role':'robot companion'}]}
    p['stages']['J04']={'locations':[{'id':'garden','purpose':'Kite rescue'}]}
    p['stages']['J05']={'units':[{'id':'u1','text':'Mina watches her red kite catch the wind.','characters':['mina','pip'],'location':'garden'},{'id':'u2','text':'Pip holds the spool while Mina reaches the kite.','characters':['mina','pip'],'location':'garden'},{'id':'u3','text':'Together they '+ending,'characters':['mina','pip'],'location':'garden'}]}
    p['stages']['J06']={'characters':[{'id':'mina','appearance':'Yellow jacket, dark curls','sheetRequired':True},{'id':'pip','appearance':'Small blue robot, round eyes','sheetRequired':True}]}
    p['stages']['J07']={'locations':[{'id':'garden','anchors':['oak tree','wooden bench'],'sheetRequired':True}]}
    return {'package':pack(p)}

